INSERT INTO `quest_template` (`entry`,`Method`,`ZoneOrSort`,`MinLevel`,`QuestLevel`,`Type`,`QuestFlags`,
  `SpecialFlags`,`RequiredCondition`,`RewXP`,`RewOrReqMoney`,`RewMoneyMaxLevel`,
  `RewItemId1`,`RewItemCount1`,`ReqCreatureOrGOId1`,`ReqCreatureOrGOCount1`,
  `Title`,`Details`,`Objectives`,`ObjectiveText1`,`RequestItemsText`,`OfferRewardText`) VALUES
  (920210,2,-9100,1,1,0,320,2049,920132,0,0,0,919602,1,920260,3,'Take a Seat','The field does not hold itself, $N. Every game at the table teaches you something about the heroes, the tavern and the allies beside you.$B$BSit down this week and play three.','Play three games of Warsong Battlegrounds.','Games played','Three games, $N. Win or lose, they all count.','Three games played. You are starting to read the tavern, and that is half of it.'),
  (920211,2,-9100,1,1,0,320,2049,920132,0,0,0,919602,1,920261,40,'Fresh from the Tavern','Bob keeps a good stock and an eager eye on your purse. A warband is built one purchase at a time.$B$BBuy forty minions from the tavern this week, across as many games as it takes.','Buy forty minions from Bob''s Tavern.','Minions bought','Forty, $N. Bob is counting too.','Forty minions bought. Bob will remember your face, and your gold.'),
  (920212,2,-9100,1,1,0,320,2049,920132,0,0,0,919602,1,920262,20,'Clearing the Board','A good player knows when to let a minion go. Every warband has room for only so much.$B$BSell twenty minions this week and make room for better ones.','Sell twenty minions.','Minions sold','Twenty sold, $N. Do not get sentimental about the small ones.','Twenty minions sold, and a sharper warband for it.'),
  (920213,2,-9100,1,1,0,320,2049,920132,0,0,0,919602,1,920263,25,'Call on Your Hero','Your hero did not come to the field for show, $N. Their power is worth little unused.$B$BCall on it twenty-five times this week.','Use your hero power twenty-five times.','Hero powers used','Twenty-five, $N. A hero that rests is a hero wasted.','Your hero is warmed up. Well used.'),
  (920214,2,-9100,1,1,0,320,2049,920132,0,0,0,919602,1,920264,1,'A Field Held','Four against four, and the last side standing keeps the field. It is not a solo contest, whatever the table makes you feel.$B$BHelp your side win a game this week.','Win a game of Warsong Battlegrounds with your team.','Games won by your team','Your side still has to win, $N.','The field is yours this week. Your side thanks you.'),
  (920215,2,-9100,1,1,0,320,2049,920132,0,0,0,919602,1,920265,3,'The Upper Half','Surviving the early rounds is easy. Staying alive while the heroes around you fall is the real test.$B$BFinish in the top four three times this week.','Finish in the top four of a game three times.','Top four finishes','Top four, $N, three times.','Three times in the upper half. The others are starting to notice.'),
  (920216,2,-9100,1,1,0,320,2049,920132,0,0,0,919602,1,920266,2,'Two Fields Held','One victory is luck. Two is a habit.$B$BHelp your side win two games this week.','Win two games of Warsong Battlegrounds with your team.','Games won by your team','Two victories, $N. Your side is counting on it.','Two fields held. Take a bow, and then take a seat.'),
  (920217,2,-9100,1,1,0,320,2049,920132,0,0,0,919602,1,920267,3,'A Rising Tavern','Bob only brings out his best for those who have earned it. The higher the tavern, the stronger the minions on offer.$B$BReach tavern tier five in three games this week.','Reach tavern tier five in three games.','Games reaching tavern tier 5','Three games, $N, with the tavern at tier five.','Bob only shows the best stock to the patient. You have been patient.'),
  (920218,2,-9100,1,1,0,320,2049,920132,0,0,0,919602,1,920268,5,'Golden Hands','Three of a kind makes a golden minion, stronger than the sum of its parts. A sharp eye finds the copies before anyone else does.$B$BMake five golden minions this week.','Make five golden minions.','Golden minions made','Five golden minions, $N. Do not let the copies slip past.','Five golden minions. Your warband shines.'),
  (920219,2,-9100,1,1,0,320,2049,920132,0,0,0,919602,1,920269,30,'The Spellslinger','Bananas, coins and worse. A hand full of spells is a hand full of choices, and a good player spends them well.$B$BCast thirty spells this week.','Cast thirty spells.','Spells cast','Thirty spells, $N. Do not let them rot in your hand.','Thirty spells cast. Well played, spellslinger.'),
  (920220,2,-9100,1,1,0,320,2049,920132,0,0,0,919602,1,920270,40,'Call of the Wild','Claws, fangs and a loyal heart. The Beasts do not ask many questions.$B$BPlay forty Beasts this week, across as many games as it takes.','Play forty Beasts.','Beasts played','Forty Beasts, $N. They will not play themselves.','Forty Beasts played. You know them well now.'),
  (920221,2,-9100,1,1,0,320,2049,920132,0,0,0,919602,1,920271,40,'A Deal with Demons','Power always has a price, and the Demons are happy to name it.$B$BPlay forty Demons this week, across as many games as it takes.','Play forty Demons.','Demons played','Forty Demons, $N. They will not play themselves.','Forty Demons played. You know them well now.'),
  (920222,2,-9100,1,1,0,320,2049,920132,0,0,0,919602,1,920272,40,'Dragonflight','A Dragon on the board changes how the whole table plays.$B$BPlay forty Dragons this week, across as many games as it takes.','Play forty Dragons.','Dragons played','Forty Dragons, $N. They will not play themselves.','Forty Dragons played. You know them well now.'),
  (920223,2,-9100,1,1,0,320,2049,920132,0,0,0,919602,1,920273,40,'Elemental Forces','Fire, water, earth and air do not take orders. They take opportunities.$B$BPlay forty Elementals this week, across as many games as it takes.','Play forty Elementals.','Elementals played','Forty Elementals, $N. They will not play themselves.','Forty Elementals played. You know them well now.'),
  (920224,2,-9100,1,1,0,320,2049,920132,0,0,0,919602,1,920274,40,'The Clockwork Army','Gears, bolts and plenty of Divine Shield. Mechs make a steady warband.$B$BPlay forty Mechs this week, across as many games as it takes.','Play forty Mechs.','Mechs played','Forty Mechs, $N. They will not play themselves.','Forty Mechs played. You know them well now.'),
  (920225,2,-9100,1,1,0,320,2049,920132,0,0,0,919602,1,920275,40,'Mrglglglgl','Nobody understands them, and nobody ignores them for long.$B$BPlay forty Murlocs this week, across as many games as it takes.','Play forty Murlocs.','Murlocs played','Forty Murlocs, $N. They will not play themselves.','Forty Murlocs played. You know them well now.'),
  (920226,2,-9100,1,1,0,320,2049,920132,0,0,0,919602,1,920276,40,'Tide of the Naga','The Naga rise from the deep with spells and patience.$B$BPlay forty Naga this week, across as many games as it takes.','Play forty Naga.','Naga played','Forty Naga, $N. They will not play themselves.','Forty Naga played. You know them well now.'),
  (920227,2,-9100,1,1,0,320,2049,920132,0,0,0,919602,1,920277,40,'Yo Ho Ho','Gold, plunder and no manners at all. The Pirates have their ways.$B$BPlay forty Pirates this week, across as many games as it takes.','Play forty Pirates.','Pirates played','Forty Pirates, $N. They will not play themselves.','Forty Pirates played. You know them well now.'),
  (920228,2,-9100,1,1,0,320,2049,920132,0,0,0,919602,1,920278,40,'The Razorfen Rally','Quilboar are tough, loud and fond of Blood Gems.$B$BPlay forty Quilboar this week, across as many games as it takes.','Play forty Quilboar.','Quilboar played','Forty Quilboar, $N. They will not play themselves.','Forty Quilboar played. You know them well now.'),
  (920229,2,-9100,1,1,0,320,2049,920132,0,0,0,919602,1,920279,4,'Hold the Field','Anyone can win a game when the cards fall their way. Holding the field week after week is something else.$B$BHelp your side win four games this week.','Win four games of Warsong Battlegrounds with your team.','Games won by your team','Four, $N. Your side is counting on you.','Four victories. The field is yours, and everyone knows who held it.'),
  (920230,2,-9100,1,1,0,320,2049,920132,0,0,0,919602,1,920280,2,'Top of the Table','Standing last on the field is a fine thing. Standing alone on it is better.$B$BFinish first twice this week.','Finish first in two games.','First places','Twice, $N. Not second. First.','Twice on top of the table. Take your pack, champion.'),
  (920231,2,-9100,1,1,0,320,2049,920132,0,0,0,919602,1,920281,4,'A Tavern at the Top','Tier six is where the best minions live, and the longest games end. Few get there, and fewer get there often.$B$BReach tavern tier six in four games this week.','Reach tavern tier six in four games.','Games reaching tavern tier 6','Four games at tier six, $N. Keep climbing.','Four times at the top of the tavern. Bob should offer you a seat.'),
  (920232,2,-9100,1,1,0,320,2049,920132,0,0,0,919602,1,920282,12,'Heart of Gold','A golden warband is a thing of beauty. Twelve of them in a week is greed, and I admire it.$B$BMake twelve golden minions this week.','Make twelve golden minions.','Golden minions made','Twelve, $N. Not eleven.','Twelve golden minions. You have the Midas touch.'),
  (920233,2,-9100,1,1,0,320,2049,920132,0,0,0,919602,1,920283,30,'Fresh Stock','Bob does not always show his best on the first look. A patient player asks for another.$B$BRefresh the tavern thirty times this week.','Refresh the tavern thirty times.','Tavern refreshes','Thirty, $N. Bob does not mind.','Thirty refreshes. Bob is tired and you are better informed.'),
  (920234,2,-9100,1,1,0,320,2049,920132,0,0,0,919602,1,920284,5,'Won on the Field','Every round your warband meets one from the other side. Winning takes more than a good board, it takes a good turn.$B$BWin five combats this week, in whatever games it takes.','Win five combats.','Combats won','Five combats, $N. A draw does not count.','Five combats won. Your warband knows its work.'),
  (920235,2,-9100,1,1,0,320,2049,920132,0,0,0,919602,1,920285,3,'Make Them Bleed','A win only counts for what it takes from the other side. Heroes do not fall on their own.$B$BDeal three hundred damage to enemy heroes this week, in whatever games it takes.','Deal 300 damage to enemy heroes by winning combats.','Damage in tens dealt to heroes','Three hundred, $N. Every point counts.','Three hundred damage dealt. Their heroes will remember it.'),
  (920236,2,-9100,1,1,0,320,2049,920132,0,0,0,919602,1,920286,60,'Make Them Stronger','A warband is only as good as its growing. Every point of Attack and Health is a promise kept.$B$BBuff your minions sixty times this week. Every effect that lifts the stats of a minion in your hand or on your board counts.','Increase the stats of your minions sixty times.','Minions buffed','Sixty, $N. Every bit counts.','Sixty buffs. Your warband has never been so well fed.'),
  (920237,2,-9100,1,1,0,320,2049,920132,0,0,0,919602,1,920287,25,'Battle Cries','A Battlecry is a minion announcing itself, and a smart player makes sure the whole table hears.$B$BPlay twenty-five minions with a Battlecry this week.','Play twenty-five minions with a Battlecry.','Battlecries played','Twenty-five, $N. Let them shout.','Twenty-five Battlecries. They heard you in the Gulch.'),
  (920238,2,-9100,1,1,0,320,2049,920132,0,0,0,919602,1,920288,40,'Last Words','The best minions are the ones that are still useful after they fall. Some of them have a last word to say.$B$BTrigger forty Deathrattles in combat this week.','Trigger forty Deathrattles in combat.','Deathrattles triggered','Forty, $N. Let them fall with a purpose.','Forty last words spoken. They were worth hearing.'),
  (920239,2,-9100,1,1,0,320,2049,920132,0,0,0,919602,1,920289,60,'Clearing the Field','Every minion that falls on the other side is one less to fear.$B$BDestroy sixty enemy minions in combat this week.','Destroy sixty enemy minions in combat.','Enemy minions destroyed','Sixty, $N. Not a drop of mercy.','Sixty enemy minions fallen. The field is quiet.'),
  (920240,2,-9100,1,1,0,320,2049,920132,0,0,0,919602,1,920290,6,'A Heavy Hand','There is a difference between winning a fight and breaking an opponent. The best players do both.$B$BDeal six hundred damage to enemy heroes this week.','Deal 600 damage to enemy heroes by winning combats.','Damage in tens dealt to heroes','Six hundred, $N. They will not forget this week.','Six hundred damage dealt. Their heroes are still counting.'),
  (920241,2,-9100,1,1,0,320,2049,920132,0,0,0,919602,1,920291,40,'The Unbroken Line','Anyone can hold a line for a round or two. The long games decide who holds it for good.$B$BWin forty combats this week, in whatever games it takes.','Win forty combats.','Combats won','Forty, $N. Draws do not count.','Forty combats won. Your line has not broken once.'),
  (920242,2,-9100,1,1,0,320,2049,920132,0,0,0,919602,1,920292,60,'Voices from Beyond','The minions you lose should do as much work as the ones you keep.$B$BTrigger sixty Deathrattles in combat this week.','Trigger sixty Deathrattles in combat.','Deathrattles triggered','Sixty, $N. The dead have plenty to say.','Sixty Deathrattles. Even in death your warband gets the last word.');
